import type { StrapiMedia, StrapiMediaFormat } from '~/types/strapi'

/**
 * Builds a Strapi v5 media object that is byte-shape-identical to what an
 * `/api/upload` populate returns: relative `url`, a `formats` map with relative
 * URLs, intrinsic `width`/`height`, `documentId`, mime, provider, etc.
 *
 * The main `url` points at a real file shipped in /public/uploads (generated by
 * scripts/gen-placeholders.mjs). The `formats` entries are present for shape
 * fidelity only — rendering uses <NuxtImg> responsive generation from the
 * source, so those variant files do not need to exist on disk.
 */

// Deterministic timestamps (no Date.now — keeps mocks stable & test-friendly).
export const MOCK_TS = '2025-05-01T09:00:00.000Z'

let mediaIdSeq = 1000

const BREAKPOINTS: { key: string; size: number }[] = [
  { key: 'thumbnail', size: 245 },
  { key: 'small', size: 500 },
  { key: 'medium', size: 750 },
  { key: 'large', size: 1000 },
]

function slugifyDocId(name: string): string {
  return (
    'mock_' +
    name
      .replace(/\.[a-z0-9]+$/i, '')
      .replace(/[^a-z0-9]+/gi, '')
      .toLowerCase()
  )
}

function buildFormat(
  key: string,
  fileName: string,
  longSide: number,
  width: number,
  height: number,
): StrapiMediaFormat {
  const scale = longSide / Math.max(width, height)
  const w = Math.round(width * scale)
  const h = Math.round(height * scale)
  return {
    name: `${key}_${fileName}`,
    hash: `${key}_${slugifyDocId(fileName)}`,
    ext: '.png',
    mime: 'image/png',
    path: null,
    width: w,
    height: h,
    size: Number(((w * h) / 4000).toFixed(2)),
    sizeInBytes: Math.round((w * h) / 4),
    url: `/uploads/${key}_${fileName}`,
  }
}

export function media(
  fileName: string,
  width: number,
  height: number,
  alternativeText: string,
): StrapiMedia {
  const longest = Math.max(width, height)
  const formats: Record<string, StrapiMediaFormat> = {}
  for (const bp of BREAKPOINTS) {
    // Strapi only emits a format when it is smaller than the original.
    if (bp.size < longest) {
      formats[bp.key] = buildFormat(bp.key, fileName, bp.size, width, height)
    }
  }

  const id = mediaIdSeq++
  return {
    id,
    documentId: slugifyDocId(fileName),
    name: fileName,
    alternativeText,
    caption: null,
    width,
    height,
    formats: Object.keys(formats).length ? formats : null,
    hash: slugifyDocId(fileName),
    ext: '.png',
    mime: 'image/png',
    size: Number(((width * height) / 4000).toFixed(2)),
    url: `/uploads/${fileName}`,
    previewUrl: null,
    provider: 'local',
    provider_metadata: null,
    createdAt: MOCK_TS,
    updatedAt: MOCK_TS,
  }
}
